                        <h3 className="text-xl font-bold text-slate-900">{app.candidateName}</h3>
                        <span className="text-[10px] font-bold bg-slate-100 text-slate-500 px-2 py-0.5 uppercase">Candidato</span>
                      </div>
                      <p className="text-sm text-slate-500 font-medium mb-4">{app.email} &bull; {app.phone}</p>
                      <div className="bg-slate-50 p-5 border-l-4 border-brand italic text-slate-600 text-sm leading-relaxed">
                        "{app.cover_letter}"
                      </div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[180px]">
                      <a 
                        href={app.cvBase64} 
                        download={app.cvFileName} 
                        className="bg-slate-900 text-white px-6 py-3 text-sm font-bold text-center hover:bg-slate-800 transition-colors uppercase tracking-tight"
                      >
                        Visualizza CV
                      </a>
                      <p className="text-[10px] text-center text-slate-400 font-bold uppercase">Ricevuto il: {new Date(app.appliedAt).toLocaleDateString('it-IT')}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="bg-white border border-slate-200 p-20 text-center">
                  <p className="text-slate-400">Nessuna candidatura ancora ricevuta.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && (
          <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />
        )}

        {view === 'ADMIN_SETTINGS' && isAuthenticated && (
          <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} />
        )}

        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-4">
            <JobForm initialData={editingJob || undefined} onSubmit={handleAddJob} onCancel={() => setView('ADMIN')} />
          </div>
        )}
      </main>

      {isApplyModalOpen && selectedJob && (
        <ApplicationModal job={selectedJob} isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} onSubmit={handleApply} />
      )}
    </div>
  );
};

