        const { error } = await supabase
          .from('jobs')
          .update(dbJob)
          .eq('id', editingJob.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('jobs')
          .insert([{ ...dbJob, posted_at: new Date().toISOString() }]);
        if (error) throw error;
      }

      await fetchData();
      setEditingJob(null);
      setView('ADMIN');
